              key={item.label}
              style={{
                border: '1px solid rgba(148, 163, 184, 0.2)',
                borderRadius: '12px',
                padding: '1rem',
                background: 'rgba(30, 41, 59, 0.6)'
              }}
            >
              <h2 style={{ fontSize: '1.1rem', marginBottom: '0.35rem' }}>{item.label}</h2>
              <p style={{ fontSize: '0.95rem', margin: 0, color: '#cbd5f5' }}>{item.detail}</p>
            </div>
          ))}
        </div>
        <div style={{ marginTop: '2rem' }}>
          <Link
            href=\"/\"
            style={{
              display: 'inline-block',
              padding: '0.75rem 1.25rem',
              borderRadius: '999px',
              background: '#38bdf8',
              color: '#0f172a',
              fontWeight: 600,
              textDecoration: 'none'
            }}
          >
            Back to Home
          </Link>
        </div>
      </section>
    </main>
  );
}
EOF"

